#include <fstream>
#include <string>

#include <nlohmann/json.hpp>

using json = nlohmann::json;

struct Config {
  std::string host;
  int port;
  int timeout_ms;
};

Config load_config(const std::string& path) {
  std::ifstream in(path);
  json j = json::parse(in);

  Config config;
  config.host = j["host"];
  config.port = j["port"];
  config.timeout_ms = j["timeout_ms"];
  return config;
}

